INSERT INTO lessons VALUES('P1B-U04-L1',1,'term-b-cooperation-v1',1,'B',4,'我会做的小动作','{"id":"P1B-U04-L1","unitId":"P1B-U04","grade":1,"term":"B","unitNumber":4,"unitLesson":1,"order":13,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":10,"title":"我会做的小动作","homeActivity":"和家人选一个自己会做的安全小动作，用I can…说一句；也可以只指图片，不需要现场表演。","releaseId":"term-b-cooperation-v1","unitTitle":"一起动起来","cards":[{"title":"我会做的小动作","rule":"说自己会做什么，用I can加动作原形。can后不加to，也不把动作加s。每个人会做的事不同，练习按文字中的人物回答，不比较谁更厉害。","example":"I can clap my hands.","translation":"我会拍手。"},{"title":"我会做的小动作","rule":"说自己会做什么，用I can加动作原形。can后不加to，也不把动作加s。每个人会做的事不同，练习按文字中的人物回答，不比较谁更厉害。","example":"Mimi can hop.","translation":"Mimi会单脚跳。"},{"title":"我会做的小动作","rule":"说自己会做什么，用I can加动作原形。can后不加to，也不把动作加s。每个人会做的事不同，练习按文字中的人物回答，不比较谁更厉害。","example":"We can roll the ball.","translation":"我们会滚球。"}],"vocabulary":[{"word":"clap","meaning":"拍手"},{"word":"hop","meaning":"单脚跳"},{"word":"roll","meaning":"滚动"},{"word":"can","meaning":"会；能够"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P1B-U04-L2',1,'term-b-cooperation-v1',1,'B',4,'暂时不会也没关系','{"id":"P1B-U04-L2","unitId":"P1B-U04","grade":1,"term":"B","unitNumber":4,"unitLesson":2,"order":14,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":10,"title":"暂时不会也没关系","homeActivity":"用I can''t…yet说一件正在学的事，再用中文说说希望得到什么帮助。不会也没关系。","releaseId":"term-b-cooperation-v1","unitTitle":"一起动起来","cards":[{"title":"暂时不会也没关系","rule":"说不会或不能做，用cannot或can''t加动作原形。can''t是cannot的缩写，意思相同。not不能单独代替can''t；还不会时可以慢慢学，不需要现场做动作证明。","example":"I cannot juggle.","translation":"我不会抛接杂耍球。"},{"title":"暂时不会也没关系","rule":"说不会或不能做，用cannot或can''t加动作原形。can''t是cannot的缩写，意思相同。not不能单独代替can''t；还不会时可以慢慢学，不需要现场做动作证明。","example":"Tina can''t skate yet.","translation":"Tina暂时还不会滑冰。"},{"title":"暂时不会也没关系","rule":"说不会或不能做，用cannot或can''t加动作原形。can''t是cannot的缩写，意思相同。not不能单独代替can''t；还不会时可以慢慢学，不需要现场做动作证明。","example":"We can ask for help.","translation":"我们可以寻求帮助。"}],"vocabulary":[{"word":"cannot","meaning":"不会；不能"},{"word":"yet","meaning":"还；尚"},{"word":"juggle","meaning":"抛接杂耍球"},{"word":"help","meaning":"帮助"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P1B-U04-L3',1,'term-b-cooperation-v1',1,'B',4,'问问你会不会','{"id":"P1B-U04-L3","unitId":"P1B-U04","grade":1,"term":"B","unitNumber":4,"unitLesson":3,"order":15,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":10,"title":"问问你会不会","homeActivity":"和愿意参与的家人轮流问Can you…?，可以如实回答Yes, I can或No, I can''t yet，不比赛。","releaseId":"term-b-cooperation-v1","unitTitle":"一起动起来","cards":[{"title":"问问你会不会","rule":"问你会不会，用Can you加动作原形再加问号。回答Yes, I can或No, I can''t，不用Yes, I do。本课说能力；现实中能做也不代表任何地方都允许做。","example":"Can you bounce a ball?","translation":"你会拍球吗？"},{"title":"问问你会不会","rule":"问你会不会，用Can you加动作原形再加问号。回答Yes, I can或No, I can''t，不用Yes, I do。本课说能力；现实中能做也不代表任何地方都允许做。","example":"Yes, I can.","translation":"是的，我会。"},{"title":"问问你会不会","rule":"问你会不会，用Can you加动作原形再加问号。回答Yes, I can或No, I can''t，不用Yes, I do。本课说能力；现实中能做也不代表任何地方都允许做。","example":"No, I can''t yet.","translation":"不，我暂时还不会。"}],"vocabulary":[{"word":"bounce","meaning":"拍球；弹起"},{"word":"throw","meaning":"投；扔"},{"word":"answer","meaning":"回答"},{"word":"ask","meaning":"询问"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P1B-U04-L4',1,'term-b-cooperation-v1',1,'B',4,'小队各有小本领','{"id":"P1B-U04-L4","unitId":"P1B-U04","grade":1,"term":"B","unitNumber":4,"unitLesson":4,"order":16,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":10,"title":"小队各有小本领","homeActivity":"为两位虚构队员各画一张能力卡，用…can…说说可以怎样分工，不按外貌猜能力。","releaseId":"term-b-cooperation-v1","unitTitle":"一起动起来","cards":[{"title":"小队各有小本领","rule":"说他、她或动物会做什么，仍用can加原形。She can dance不把can变成cans。看任务卡上的能力来分工，不用外貌或名字猜能力。","example":"She can carry the cards.","translation":"她能拿卡片。"},{"title":"小队各有小本领","rule":"说他、她或动物会做什么，仍用can加原形。She can dance不把can变成cans。看任务卡上的能力来分工，不用外貌或名字猜能力。","example":"He can count the beanbags.","translation":"他会数豆袋。"},{"title":"小队各有小本领","rule":"说他、她或动物会做什么，仍用can加原形。She can dance不把can变成cans。看任务卡上的能力来分工，不用外貌或名字猜能力。","example":"The dog can fetch a toy.","translation":"这只狗会叼回玩具。"}],"vocabulary":[{"word":"team","meaning":"小队"},{"word":"carry","meaning":"拿；搬"},{"word":"count","meaning":"数数"},{"word":"take turns","meaning":"轮流"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.yes-no"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U04-L1',1,'term-b-cooperation-v1',2,'B',4,'近处这些衣物','{"id":"P2B-U04-L1","unitId":"P2B-U04","grade":2,"term":"B","unitNumber":4,"unitLesson":1,"order":13,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":10,"title":"近处这些衣物","homeActivity":"把两张衣物图片放在近处，用These are…介绍。没有图片时也可画两个相同衣物。","releaseId":"term-b-cooperation-v1","unitTitle":"穿衣小助手","cards":[{"title":"近处这些衣物","rule":"these表示近处的这些，后接复数名词，搭配are。this表示近处一个，搭配is。socks、shoes等成双衣物常用复数；不因为它们是一双就直接用is。","example":"These are my socks.","translation":"这些是我的袜子。"},{"title":"近处这些衣物","rule":"these表示近处的这些，后接复数名词，搭配are。this表示近处一个，搭配is。socks、shoes等成双衣物常用复数；不因为它们是一双就直接用is。","example":"These hats are yellow.","translation":"这些帽子是黄色的。"},{"title":"近处这些衣物","rule":"these表示近处的这些，后接复数名词，搭配are。this表示近处一个，搭配is。socks、shoes等成双衣物常用复数；不因为它们是一双就直接用is。","example":"This scarf is soft.","translation":"这条围巾很柔软。"}],"vocabulary":[{"word":"these","meaning":"这些（近处）"},{"word":"socks","meaning":"袜子"},{"word":"hat","meaning":"帽子"},{"word":"scarf","meaning":"围巾"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.pronouns","grammar.be","forms.noun-plural"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U04-L2',1,'term-b-cooperation-v1',2,'B',4,'远处那些衣物','{"id":"P2B-U04-L2","unitId":"P2B-U04","grade":2,"term":"B","unitNumber":4,"unitLesson":2,"order":14,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":10,"title":"远处那些衣物","homeActivity":"和家人约定哪些衣物图片算远处，用Those are…介绍；无需真的走远或移动家具。","releaseId":"term-b-cooperation-v1","unitTitle":"穿衣小助手","cards":[{"title":"远处那些衣物","rule":"those表示远处的那些，搭配复数名词和are；that表示远处一个，搭配is。远近需要文字或画面说明，不能只凭衣物颜色决定。","example":"Those coats are blue.","translation":"那些外套是蓝色的。"},{"title":"远处那些衣物","rule":"those表示远处的那些，搭配复数名词和are；that表示远处一个，搭配is。远近需要文字或画面说明，不能只凭衣物颜色决定。","example":"Those are winter boots.","translation":"那些是冬靴。"},{"title":"远处那些衣物","rule":"those表示远处的那些，搭配复数名词和are；that表示远处一个，搭配is。远近需要文字或画面说明，不能只凭衣物颜色决定。","example":"That jacket is grey.","translation":"那件夹克是灰色的。"}],"vocabulary":[{"word":"those","meaning":"那些（远处）"},{"word":"coat","meaning":"外套"},{"word":"boots","meaning":"靴子"},{"word":"far","meaning":"远的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.pronouns","grammar.be","forms.noun-plural"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U04-L3',1,'term-b-cooperation-v1',2,'B',4,'先数一数再选词','{"id":"P2B-U04-L3","unitId":"P2B-U04","grade":2,"term":"B","unitNumber":4,"unitLesson":3,"order":15,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":10,"title":"先数一数再选词","homeActivity":"用一张鞋的图片比较These shoes are…和This pair of shoes is…，说说每句话在数什么。","releaseId":"term-b-cooperation-v1","unitTitle":"穿衣小助手","cards":[{"title":"先数一数再选词","rule":"先看一个还是多个，再看近处还是远处：this/that配单数is，these/those配复数are。trousers本身是复数；a pair of trousers说一条裤子，中心词pair是单数。","example":"This T-shirt is white.","translation":"这件T恤是白色的。"},{"title":"先数一数再选词","rule":"先看一个还是多个，再看近处还是远处：this/that配单数is，these/those配复数are。trousers本身是复数；a pair of trousers说一条裤子，中心词pair是单数。","example":"Those T-shirts are red.","translation":"那些T恤是红色的。"},{"title":"先数一数再选词","rule":"先看一个还是多个，再看近处还是远处：this/that配单数is，these/those配复数are。trousers本身是复数；a pair of trousers说一条裤子，中心词pair是单数。","example":"A pair of trousers is on the chair.","translation":"一条长裤在椅子上。"}],"vocabulary":[{"word":"pair","meaning":"双；条；副"},{"word":"trousers","meaning":"长裤"},{"word":"T-shirt","meaning":"T恤"},{"word":"one","meaning":"一个"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.pronouns","grammar.be","forms.noun-plural"],"itemCount":9}');
INSERT INTO lessons VALUES('P2B-U04-L4',1,'term-b-cooperation-v1',2,'B',4,'按衣物便条来挑选','{"id":"P2B-U04-L4","unitId":"P2B-U04","grade":2,"term":"B","unitNumber":4,"unitLesson":4,"order":16,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":10,"title":"按衣物便条来挑选","homeActivity":"画两组不同衣物，写清近处、远处，请家人按these或those的描述指出对应图片。","releaseId":"term-b-cooperation-v1","unitTitle":"穿衣小助手","cards":[{"title":"按衣物便条来挑选","rule":"描述这些或那些衣物时，把远近、数量和特征一起看。These are…可以介绍近处多个物品；Are those…?询问远处多个。选择要有便条依据，不猜别人的喜好。","example":"These are our sun hats.","translation":"这些是我们的遮阳帽。"},{"title":"按衣物便条来挑选","rule":"描述这些或那些衣物时，把远近、数量和特征一起看。These are…可以介绍近处多个物品；Are those…?询问远处多个。选择要有便条依据，不猜别人的喜好。","example":"Are those your rain boots?","translation":"那些是你的雨靴吗？"},{"title":"按衣物便条来挑选","rule":"描述这些或那些衣物时，把远近、数量和特征一起看。These are…可以介绍近处多个物品；Are those…?询问远处多个。选择要有便条依据，不猜别人的喜好。","example":"Those gloves have blue stripes.","translation":"那些手套有蓝色条纹。"}],"vocabulary":[{"word":"stripe","meaning":"条纹"},{"word":"spot","meaning":"圆点"},{"word":"sun hat","meaning":"遮阳帽"},{"word":"choose","meaning":"选择"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.pronouns","grammar.be","forms.noun-plural"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U04-L1',1,'term-b-cooperation-v1',3,'B',4,'用because说说原因','{"id":"P3B-U04-L1","unitId":"P3B-U04","grade":3,"term":"B","unitNumber":4,"unitLesson":1,"order":13,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"用because说说原因","homeActivity":"选自己喜欢的季节，用I like…because…说真实理由。家人的答案可以和你不同。","releaseId":"term-b-cooperation-v1","unitTitle":"一年四季","cards":[{"title":"用because说说原因","rule":"because后接完整原因句，常回答Why。I like spring because the flowers bloom先说喜好，再说原因。because of后常接名词，这一课先练because加句子。","example":"I like spring because the flowers bloom.","translation":"我喜欢春天，因为花开了。"},{"title":"用because说说原因","rule":"because后接完整原因句，常回答Why。I like spring because the flowers bloom先说喜好，再说原因。because of后常接名词，这一课先练because加句子。","example":"Rosa likes summer because she enjoys long days.","translation":"Rosa喜欢夏天，因为她喜欢白天长。"},{"title":"用because说说原因","rule":"because后接完整原因句，常回答Why。I like spring because the flowers bloom先说喜好，再说原因。because of后常接名词，这一课先练because加句子。","example":"Why do you like autumn?","translation":"你为什么喜欢秋天？"}],"vocabulary":[{"word":"spring","meaning":"春天"},{"word":"summer","meaning":"夏天"},{"word":"bloom","meaning":"开花"},{"word":"because","meaning":"因为"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.connectives","reading.details"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U04-L2',1,'term-b-cooperation-v1',3,'B',4,'天气理由要有依据','{"id":"P3B-U04-L2","unitId":"P3B-U04","grade":3,"term":"B","unitNumber":4,"unitLesson":2,"order":14,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"天气理由要有依据","homeActivity":"和家人读一条当地天气描述，只根据给出的信息说一句because原因，不猜别处的天气。","releaseId":"term-b-cooperation-v1","unitTitle":"一年四季","cards":[{"title":"天气理由要有依据","rule":"天气因地区而不同，不能说每个地方冬天都下雪。阅读先找人物所在的地方和原文天气，再用because解释选择。原文没说的原因不能当成证据。","example":"In this town, winter is usually dry.","translation":"在这座城镇，冬天通常干燥。"},{"title":"天气理由要有依据","rule":"天气因地区而不同，不能说每个地方冬天都下雪。阅读先找人物所在的地方和原文天气，再用because解释选择。原文没说的原因不能当成证据。","example":"We use the hall because the field is wet.","translation":"我们使用礼堂，因为场地湿了。"},{"title":"天气理由要有依据","rule":"天气因地区而不同，不能说每个地方冬天都下雪。阅读先找人物所在的地方和原文天气，再用because解释选择。原文没说的原因不能当成证据。","example":"The story does not mention snow.","translation":"故事没有提到雪。"}],"vocabulary":[{"word":"dry","meaning":"干燥的"},{"word":"wet","meaning":"湿的"},{"word":"weather","meaning":"天气"},{"word":"town","meaning":"城镇"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.connectives","reading.details"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U04-L3',1,'term-b-cooperation-v1',3,'B',4,'原因不是结果','{"id":"P3B-U04-L3","unitId":"P3B-U04","grade":3,"term":"B","unitNumber":4,"unitLesson":3,"order":15,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"原因不是结果","homeActivity":"画一张因果卡：一边写原因，一边写结果，分别用because和so表达相同关系。","releaseId":"term-b-cooperation-v1","unitTitle":"一年四季","cards":[{"title":"原因不是结果","rule":"because带出原因；so带出结果。同一个关系可换顺序表达，但本课不用Because…so…同时连接同一对句子。先问“为什么”，再看哪一部分是结果。","example":"It is windy, so we close the window.","translation":"刮风了，所以我们关窗。"},{"title":"原因不是结果","rule":"because带出原因；so带出结果。同一个关系可换顺序表达，但本课不用Because…so…同时连接同一对句子。先问“为什么”，再看哪一部分是结果。","example":"We close the window because it is windy.","translation":"我们关窗，因为刮风了。"},{"title":"原因不是结果","rule":"because带出原因；so带出结果。同一个关系可换顺序表达，但本课不用Because…so…同时连接同一对句子。先问“为什么”，再看哪一部分是结果。","example":"The leaves fall because the wind shakes them.","translation":"树叶落下，因为风把它们摇落。"}],"vocabulary":[{"word":"reason","meaning":"原因"},{"word":"result","meaning":"结果"},{"word":"windy","meaning":"多风的"},{"word":"shade","meaning":"阴凉处"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.connectives","reading.details"],"itemCount":9}');
INSERT INTO lessons VALUES('P3B-U04-L4',1,'term-b-cooperation-v1',3,'B',4,'季节喜好各有理由','{"id":"P3B-U04-L4","unitId":"P3B-U04","grade":3,"term":"B","unitNumber":4,"unitLesson":4,"order":16,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"季节喜好各有理由","homeActivity":"问愿意参与的家人Why do you like…?，复述对方给出的理由，不把自己的喜好当成对方的。","releaseId":"term-b-cooperation-v1","unitTitle":"一年四季","cards":[{"title":"季节喜好各有理由","rule":"别人喜欢的季节可以和自己不同。读Why…?先找对应人物的because原因。but连接不同看法，because说明自己的理由；有证据的喜好没有统一正确季节。","example":"I like cool mornings, but Kai likes warm evenings.","translation":"我喜欢凉爽早晨，但Kai喜欢温暖傍晚。"},{"title":"季节喜好各有理由","rule":"别人喜欢的季节可以和自己不同。读Why…?先找对应人物的because原因。but连接不同看法，because说明自己的理由；有证据的喜好没有统一正确季节。","example":"Kai likes summer because he can see fireflies.","translation":"Kai喜欢夏天，因为他能看到萤火虫。"},{"title":"季节喜好各有理由","rule":"别人喜欢的季节可以和自己不同。读Why…?先找对应人物的because原因。but连接不同看法，because说明自己的理由；有证据的喜好没有统一正确季节。","example":"We can have different favourites.","translation":"我们可以有不同喜好。"}],"vocabulary":[{"word":"favourite","meaning":"最喜欢的"},{"word":"morning","meaning":"早晨"},{"word":"evening","meaning":"傍晚"},{"word":"different","meaning":"不同的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.connectives","reading.details"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U04-L1',1,'term-b-cooperation-v1',4,'B',4,'必须做的事','{"id":"P4B-U04-L1","unitId":"P4B-U04","grade":4,"term":"B","unitNumber":4,"unitLesson":1,"order":13,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"必须做的事","homeActivity":"和家人选一条你们确认过的真实场所规则，用must说清必须做什么；不确定时先问成人。","releaseId":"term-b-cooperation-v1","unitTitle":"安全与规则","cards":[{"title":"必须做的事","rule":"must加动词原形表达必须遵守的要求，主语换成he或she也不加s。规则要有场景与发布者，本课按虚构活动室的海报回答，不把一张海报当成所有场所的规定。","example":"We must walk in this activity room.","translation":"在这个活动室，我们必须步行。"},{"title":"必须做的事","rule":"must加动词原形表达必须遵守的要求，主语换成he或she也不加s。规则要有场景与发布者，本课按虚构活动室的海报回答，不把一张海报当成所有场所的规定。","example":"Each visitor must wear a badge here.","translation":"这里每位访客必须戴徽章。"},{"title":"必须做的事","rule":"must加动词原形表达必须遵守的要求，主语换成he或she也不加s。规则要有场景与发布者，本课按虚构活动室的海报回答，不把一张海报当成所有场所的规定。","example":"You must follow the adult''s instructions.","translation":"你必须听从带队成人的指示。"}],"vocabulary":[{"word":"must","meaning":"必须"},{"word":"rule","meaning":"规则"},{"word":"visitor","meaning":"访客"},{"word":"badge","meaning":"徽章"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.patterns.modals"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U04-L2',1,'term-b-cooperation-v1',4,'B',4,'不许和不必不一样','{"id":"P4B-U04-L2","unitId":"P4B-U04","grade":4,"term":"B","unitNumber":4,"unitLesson":2,"order":14,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"不许和不必不一样","homeActivity":"画两张虚构便条，一张表示不许做，一张表示不必自带，用mustn''t和don''t have to分别说明。","releaseId":"term-b-cooperation-v1","unitTitle":"安全与规则","cards":[{"title":"不许和不必不一样","rule":"mustn''t或must not表示不许；don''t have to表示不必，并不是禁止。例如不许触摸展品，不代表不必触摸。先判断海报是在禁止还是说没有必要。","example":"You mustn''t touch the display.","translation":"你不许触摸展品。"},{"title":"不许和不必不一样","rule":"mustn''t或must not表示不许；don''t have to表示不必，并不是禁止。例如不许触摸展品，不代表不必触摸。先判断海报是在禁止还是说没有必要。","example":"You must not lean on the glass.","translation":"你不许倚靠玻璃。"},{"title":"不许和不必不一样","rule":"mustn''t或must not表示不许；don''t have to表示不必，并不是禁止。例如不许触摸展品，不代表不必触摸。先判断海报是在禁止还是说没有必要。","example":"You don''t have to bring a pencil; we provide one.","translation":"你不必带铅笔，我们会提供。"}],"vocabulary":[{"word":"mustn''t","meaning":"不许"},{"word":"display","meaning":"展品"},{"word":"provide","meaning":"提供"},{"word":"necessary","meaning":"必要的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.patterns.modals"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U04-L3',1,'term-b-cooperation-v1',4,'B',4,'规则后面有理由','{"id":"P4B-U04-L3","unitId":"P4B-U04","grade":4,"term":"B","unitNumber":4,"unitLesson":3,"order":15,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"规则后面有理由","homeActivity":"为虚构活动室写一条must或mustn''t规则，加because解释相符的原因，成人可一起核对。","releaseId":"term-b-cooperation-v1","unitTitle":"安全与规则","cards":[{"title":"规则后面有理由","rule":"must/mustn''t说明要求，because补上原因。读海报时把要求与对应理由配起来，不能用一个无关的理由解释规则。真实活动仍听现场成人和正式标识。","example":"We must keep the floor dry because wet floors can be slippery.","translation":"必须保持地面干燥，因为湿地面可能打滑。"},{"title":"规则后面有理由","rule":"must/mustn''t说明要求，because补上原因。读海报时把要求与对应理由配起来，不能用一个无关的理由解释规则。真实活动仍听现场成人和正式标识。","example":"We mustn''t shout because another group is listening.","translation":"不能大喊，因为另一组正在听讲。"},{"title":"规则后面有理由","rule":"must/mustn''t说明要求，because补上原因。读海报时把要求与对应理由配起来，不能用一个无关的理由解释规则。真实活动仍听现场成人和正式标识。","example":"Ask an adult if a sign is unclear.","translation":"标识不清楚时问成人。"}],"vocabulary":[{"word":"warning","meaning":"警示"},{"word":"clear","meaning":"清楚的；畅通的"},{"word":"slippery","meaning":"滑的"},{"word":"quietly","meaning":"轻声地"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.patterns.modals"],"itemCount":9}');
INSERT INTO lessons VALUES('P4B-U04-L4',1,'term-b-cooperation-v1',4,'B',4,'写清楚一张提示卡','{"id":"P4B-U04-L4","unitId":"P4B-U04","grade":4,"term":"B","unitNumber":4,"unitLesson":4,"order":16,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"写清楚一张提示卡","homeActivity":"和家人角色扮演：用Must we bring…?问材料是否必须自带，用明确的肯定或不必回答。","releaseId":"term-b-cooperation-v1","unitTitle":"安全与规则","cards":[{"title":"写清楚一张提示卡","rule":"提示卡写清地点、要求和动作。Must we…?是在询问是否必须，答Yes, you must；否定回答表示不必时用No, you don''t have to，不能误用mustn''t变成禁止。","example":"Must we bring our own glue?","translation":"我们必须自带胶水吗？"},{"title":"写清楚一张提示卡","rule":"提示卡写清地点、要求和动作。Must we…?是在询问是否必须，答Yes, you must；否定回答表示不必时用No, you don''t have to，不能误用mustn''t变成禁止。","example":"No, you don''t have to; glue is provided.","translation":"不必，会提供胶水。"},{"title":"写清楚一张提示卡","rule":"提示卡写清地点、要求和动作。Must we…?是在询问是否必须，答Yes, you must；否定回答表示不必时用No, you don''t have to，不能误用mustn''t变成禁止。","example":"Yes, you must wear the workshop badge.","translation":"是的，必须佩戴工坊徽章。"}],"vocabulary":[{"word":"instruction","meaning":"说明；指令"},{"word":"own","meaning":"自己的"},{"word":"glue","meaning":"胶水"},{"word":"poster","meaning":"海报"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.modals","sentence.patterns.modals"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U04-L1',1,'term-b-cooperation-v1',5,'B',4,'many数个数，much说总量','{"id":"P5B-U04-L1","unitId":"P5B-U04","grade":5,"term":"B","unitNumber":4,"unitLesson":1,"order":13,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"many数个数，much说总量","homeActivity":"在纸上画两种可数食物和两种按总量说的食物，分别问How many或How much，不必准备真食物。","releaseId":"term-b-cooperation-v1","unitTitle":"美食与文化","cards":[{"title":"many数个数，much说总量","rule":"many修饰可数复数，much修饰不可数名词；How many问个数，How much问量或价格。本课rice按米饭总量是不可数，rice grains说一粒粒米可数，不能只按中文有没有量词判断。","example":"How many dumplings are on the plate?","translation":"盘里有几个饺子？"},{"title":"many数个数，much说总量","rule":"many修饰可数复数，much修饰不可数名词；How many问个数，How much问量或价格。本课rice按米饭总量是不可数，rice grains说一粒粒米可数，不能只按中文有没有量词判断。","example":"How much rice do we need?","translation":"我们需要多少米饭？"},{"title":"many数个数，much说总量","rule":"many修饰可数复数，much修饰不可数名词；How many问个数，How much问量或价格。本课rice按米饭总量是不可数，rice grains说一粒粒米可数，不能只按中文有没有量词判断。","example":"There isn''t much soup left.","translation":"剩下的汤不多了。"}],"vocabulary":[{"word":"dumpling","meaning":"饺子"},{"word":"rice","meaning":"米饭；大米"},{"word":"soup","meaning":"汤"},{"word":"amount","meaning":"数量；总量"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.countability","grammar.quantifiers","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U04-L2',1,'term-b-cooperation-v1',5,'B',4,'a few和a little小份量','{"id":"P5B-U04-L2","unitId":"P5B-U04","grade":5,"term":"B","unitNumber":4,"unitLesson":2,"order":14,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"a few和a little小份量","homeActivity":"设计一份虚构小菜单，用a few和a little各写一句。只做语言练习，不需要实际烹饪或品尝。","releaseId":"term-b-cooperation-v1","unitTitle":"美食与文化","cards":[{"title":"a few和a little小份量","rule":"a few加可数复数，a little加不可数名词，都表示有少量。few/little不带a时通常强调少到不够或几乎没有；不能随意删去a。份量与数量要按给定菜单描述。","example":"We have a few olives.","translation":"我们有几颗橄榄。"},{"title":"a few和a little小份量","rule":"a few加可数复数，a little加不可数名词，都表示有少量。few/little不带a时通常强调少到不够或几乎没有；不能随意删去a。份量与数量要按给定菜单描述。","example":"We have a little yogurt.","translation":"我们有一点酸奶。"},{"title":"a few和a little小份量","rule":"a few加可数复数，a little加不可数名词，都表示有少量。few/little不带a时通常强调少到不够或几乎没有；不能随意删去a。份量与数量要按给定菜单描述。","example":"There are few olives left, so we need more.","translation":"剩下的橄榄很少，所以还需要一些。"}],"vocabulary":[{"word":"a few","meaning":"几个；少量（可数）"},{"word":"a little","meaning":"一点（不可数）"},{"word":"olive","meaning":"橄榄"},{"word":"yogurt","meaning":"酸奶"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.countability","grammar.quantifiers","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U04-L3',1,'term-b-cooperation-v1',5,'B',4,'数食物也可以数容器','{"id":"P5B-U04-L3","unitId":"P5B-U04","grade":5,"term":"B","unitNumber":4,"unitLesson":3,"order":15,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"数食物也可以数容器","homeActivity":"画两碗汤，分别问How many bowls和How much soup，说说问题是在数容器还是问总量。","releaseId":"term-b-cooperation-v1","unitTitle":"美食与文化","cards":[{"title":"数食物也可以数容器","rule":"不可数食物也能用可数单位计量：a bowl of soup、two bowls of soup。How many bowls问几碗，How much soup问汤量。数量词修饰中心词bowls，不把s加在soup上。","example":"Two bowls of noodle soup are ready.","translation":"两碗面汤准备好了。"},{"title":"数食物也可以数容器","rule":"不可数食物也能用可数单位计量：a bowl of soup、two bowls of soup。How many bowls问几碗，How much soup问汤量。数量词修饰中心词bowls，不把s加在soup上。","example":"A cup of tea is on the tray.","translation":"一杯茶在托盘上。"},{"title":"数食物也可以数容器","rule":"不可数食物也能用可数单位计量：a bowl of soup、two bowls of soup。How many bowls问几碗，How much soup问汤量。数量词修饰中心词bowls，不把s加在soup上。","example":"How many slices of bread do we need?","translation":"我们需要几片面包？"}],"vocabulary":[{"word":"bowl","meaning":"碗"},{"word":"slice","meaning":"片"},{"word":"cup","meaning":"杯"},{"word":"loaf","meaning":"一条面包"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.countability","grammar.quantifiers","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P5B-U04-L4',1,'term-b-cooperation-v1',5,'B',4,'菜单写什么就说什么','{"id":"P5B-U04-L4","unitId":"P5B-U04","grade":5,"term":"B","unitNumber":4,"unitLesson":4,"order":16,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"菜单写什么就说什么","homeActivity":"和家人读示例菜单，只介绍明确列出的配料；找不到的信息说不知道，不据此判断过敏安全。","releaseId":"term-b-cooperation-v1","unitTitle":"美食与文化","cards":[{"title":"菜单写什么就说什么","rule":"菜单里的食材和份量是证据，不能从菜名猜所有做法，也不把一种食物说成整个地区每个人都吃。比较菜品先找明确的成分，再用a few/a little或many/much说明。真实过敏问题由成人核对。","example":"This sample menu uses a little ginger.","translation":"这份示例菜单用了一点姜。"},{"title":"菜单写什么就说什么","rule":"菜单里的食材和份量是证据，不能从菜名猜所有做法，也不把一种食物说成整个地区每个人都吃。比较菜品先找明确的成分，再用a few/a little或many/much说明。真实过敏问题由成人核对。","example":"The note lists a few chopped beans.","translation":"便条列出了少量切碎的豆子。"},{"title":"菜单写什么就说什么","rule":"菜单里的食材和份量是证据，不能从菜名猜所有做法，也不把一种食物说成整个地区每个人都吃。比较菜品先找明确的成分，再用a few/a little或many/much说明。真实过敏问题由成人核对。","example":"The menu does not list every ingredient.","translation":"菜单没有列出全部配料。"}],"vocabulary":[{"word":"ingredient","meaning":"配料"},{"word":"sample","meaning":"示例；样品"},{"word":"list","meaning":"列出；清单"},{"word":"ginger","meaning":"姜"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.countability","grammar.quantifiers","sentence.wh"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U04-L1',1,'term-b-cooperation-v1',6,'B',4,'把建议说得有礼貌','{"id":"P6B-U04-L1","unitId":"P6B-U04","grade":6,"term":"B","unitNumber":4,"unitLesson":1,"order":13,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"把建议说得有礼貌","homeActivity":"为一个虚构班级活动用We could…和How about…各提一条建议，邀请对方提出不同想法。","releaseId":"term-b-cooperation-v1","unitTitle":"讨论有办法","cards":[{"title":"把建议说得有礼貌","rule":"We could加原形提出可考虑的建议；Why don''t we加原形也可提议；How about后接名词或动词ing。建议不是命令，别人可以提出不同方案或拒绝。","example":"We could make a paper model.","translation":"我们可以考虑做一个纸模型。"},{"title":"把建议说得有礼貌","rule":"We could加原形提出可考虑的建议；Why don''t we加原形也可提议；How about后接名词或动词ing。建议不是命令，别人可以提出不同方案或拒绝。","example":"Why don''t we compare both plans?","translation":"我们为什么不比较两个方案呢？"},{"title":"把建议说得有礼貌","rule":"We could加原形提出可考虑的建议；Why don''t we加原形也可提议；How about后接名词或动词ing。建议不是命令，别人可以提出不同方案或拒绝。","example":"How about sharing the materials?","translation":"共享材料怎么样？"}],"vocabulary":[{"word":"suggestion","meaning":"建议"},{"word":"consider","meaning":"考虑"},{"word":"share","meaning":"分享；共用"},{"word":"compare","meaning":"比较"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.requests","sentence.connectives","sentence.patterns.modals"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U04-L2',1,'term-b-cooperation-v1',6,'B',4,'同意一部分也能说清楚','{"id":"P6B-U04-L2","unitId":"P6B-U04","grade":6,"term":"B","unitNumber":4,"unitLesson":2,"order":14,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"同意一部分也能说清楚","homeActivity":"选两个纸上方案，用I see your point, but…说一个针对方案的顾虑，不评价提出建议的人。","releaseId":"term-b-cooperation-v1","unitTitle":"讨论有办法","cards":[{"title":"同意一部分也能说清楚","rule":"I agree with加人，agree that加句子。I see your point, but…可先回应再说明顾虑；礼貌不同意要针对方案，不贬低人。because给出理由，不假装所有人已同意。","example":"I agree with you about the colour.","translation":"关于颜色，我同意你的看法。"},{"title":"同意一部分也能说清楚","rule":"I agree with加人，agree that加句子。I see your point, but…可先回应再说明顾虑；礼貌不同意要针对方案，不贬低人。because给出理由，不假装所有人已同意。","example":"I see your point, but the box is too heavy.","translation":"我理解你的意思，但盒子太重了。"},{"title":"同意一部分也能说清楚","rule":"I agree with加人，agree that加句子。I see your point, but…可先回应再说明顾虑；礼貌不同意要针对方案，不贬低人。because给出理由，不假装所有人已同意。","example":"I prefer the smaller model because it uses less card.","translation":"我更喜欢小模型，因为它用的卡纸更少。"}],"vocabulary":[{"word":"agree","meaning":"同意"},{"word":"point","meaning":"观点"},{"word":"concern","meaning":"顾虑"},{"word":"prefer","meaning":"更喜欢"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.requests","sentence.connectives","sentence.patterns.modals"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U04-L3',1,'term-b-cooperation-v1',6,'B',4,'比较方案要看限制','{"id":"P6B-U04-L3","unitId":"P6B-U04","grade":6,"term":"B","unitNumber":4,"unitLesson":3,"order":15,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"比较方案要看限制","homeActivity":"给虚构海报设定时间与材料限制，对照两个方案核对，再用We should…说明你的理由。","releaseId":"term-b-cooperation-v1","unitTitle":"讨论有办法","cards":[{"title":"比较方案要看限制","rule":"比较建议先核对时间、材料和明确要求。should/could后接原形；should表示建议，could表示可考虑的选择，都不等于已经决定。只有比较维度相同时才能根据数据判断更合适。","example":"We should check the deadline first.","translation":"我们应该先核对截止时间。"},{"title":"比较方案要看限制","rule":"比较建议先核对时间、材料和明确要求。should/could后接原形；should表示建议，could表示可考虑的选择，都不等于已经决定。只有比较维度相同时才能根据数据判断更合适。","example":"Plan A uses less paper than Plan B.","translation":"Plan A比Plan B用纸更少。"},{"title":"比较方案要看限制","rule":"比较建议先核对时间、材料和明确要求。should/could后接原形；should表示建议，could表示可考虑的选择，都不等于已经决定。只有比较维度相同时才能根据数据判断更合适。","example":"We could choose a simpler design.","translation":"我们可以考虑更简单的设计。"}],"vocabulary":[{"word":"constraint","meaning":"限制条件"},{"word":"deadline","meaning":"截止时间"},{"word":"material","meaning":"材料"},{"word":"suitable","meaning":"合适的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.requests","sentence.connectives","sentence.patterns.modals"],"itemCount":9}');
INSERT INTO lessons VALUES('P6B-U04-L4',1,'term-b-cooperation-v1',6,'B',4,'轮流倾听再作决定','{"id":"P6B-U04-L4","unitId":"P6B-U04","grade":6,"term":"B","unitNumber":4,"unitLesson":4,"order":16,"subtitle":"下学期第四站：看清情景，说出能力、理由和合作办法","minutes":12,"title":"轮流倾听再作决定","homeActivity":"和愿意参与的家人轮流提议，分开记录已同意和未决定的内容；没有回复不记为同意。","releaseId":"term-b-cooperation-v1","unitTitle":"讨论有办法","cards":[{"title":"轮流倾听再作决定","rule":"讨论记录要分清谁建议、谁同意、哪些仍未决定。Let''s加原形邀请一起做；Shall we加原形询问一起做某事。听见一个人说could不能写成全组will；也不能把未回复当成同意。","example":"Let''s hear everyone''s idea first.","translation":"先听听每个人的想法吧。"},{"title":"轮流倾听再作决定","rule":"讨论记录要分清谁建议、谁同意、哪些仍未决定。Let''s加原形邀请一起做；Shall we加原形询问一起做某事。听见一个人说could不能写成全组will；也不能把未回复当成同意。","example":"Shall we record the points we agree on?","translation":"我们把已同意的要点记下来好吗？"},{"title":"轮流倾听再作决定","rule":"讨论记录要分清谁建议、谁同意、哪些仍未决定。Let''s加原形邀请一起做；Shall we加原形询问一起做某事。听见一个人说could不能写成全组will；也不能把未回复当成同意。","example":"The group has not chosen a plan yet.","translation":"小组还没有选定方案。"}],"vocabulary":[{"word":"take turns","meaning":"轮流"},{"word":"record","meaning":"记录"},{"word":"reply","meaning":"回复"},{"word":"decision","meaning":"决定"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["sentence.patterns.requests","sentence.connectives","sentence.patterns.modals"],"itemCount":9}');
INSERT INTO items VALUES('P1B-U04-L1.p1.listen',1,'P1B-U04-L1',1,'listening.P1B-U04','listening-choice','listen','{"title":"我会做的小动作","gradeMin":1,"id":"P1B-U04-L1.p1.listen","type":"listen","category":"vocabulary","context":"主动播放一句英文，听清后确认；听不到时可用文字辅助。","prompt":"Nono会做什么？","audioText":"Nono can wave.","choices":["挥手","画画","唱歌"]}','{"answers":["挥手"],"family":"fact-5c3b5f89df1900a9","hint":"先听人物、动作、物品或位置。需要时使用文字辅助，辅助会单独记录。","explanation":"Nono can wave. 对应答案：挥手。","solutionSentences":["Nono can wave."]}','published');
INSERT INTO release_items VALUES('term-b-cooperation-v1','P1B-U04-L1.p1.listen',1);
INSERT INTO items VALUES('P1B-U04-L1.p2.evidence',1,'P1B-U04-L1',1,'reading.P1B-U04','reading-evidence','evidence','{"title":"我会做的小动作","gradeMin":1,"id":"P1B-U04-L1.p2.evidence","type":"evidence","category":"reading","context":"读小故事，先选支持答案的原句，再回答问题。","prompt":"Bobo会接住什么？","passage":[{"id":"s1","text":"Bobo can catch a soft ball."},{"id":"s2","text":"Didi can draw a smiling sun."},{"id":"s3","text":"They practise different actions."}],"choices":["a soft ball","a paper plane","a red kite"]}','{"answers":["[\"s1\",\"a soft ball\"]"],"evidenceSolutions":[{"sentenceId":"s1","answer":"a soft ball"}],"family":"fact-2cb8dea009b7994b","hint":"回到原文找人物、地点、物品或因果；所选句子必须支持答案。","explanation":"依据：Bobo can catch a soft ball. 对应答案：a soft ball。","solutionSentences":["Bobo can catch a soft ball."]}','published');
INSERT INTO release_items VALUES('term-b-cooperation-v1','P1B-U04-L1.p2.evidence',1);
INSERT INTO items VALUES('P1B-U04-L1.p3.choice',1,'P1B-U04-L1',1,'grammar.modals.can','recognition','choice','{"title":"我会做的小动作","gradeMin":1,"id":"P1B-U04-L1.p3.choice","type":"choice","category":"grammar","context":"can后选动作原形。","prompt":"Toto can ___ a ribbon.","choices":["wave","waves","to wave"]}','{"answers":["wave"],"family":"fact-02ae26cdeae0e466","hint":"说自己会做什么，用I can加动作原形。can后不加to，也不把动作加s。每个人会做的事不同，练习按文字中的人物回答，不比较谁更厉害。","explanation":"Toto can wave a ribbon. can后选动作原形。 说自己会做什么，用I can加动作原形。can后不加to，也不把动作加s。每个人会做的事不同，练习按文字中的人物回答，不比较谁更厉害。","solutionSentences":["Toto can wave a ribbon."]}','published');
INSERT INTO release_items VALUES('term-b-cooperation-v1','P1B-U04-L1.p3.choice',1);
INSERT INTO items VALUES('P1B-U04-L1.p4.listen',1,'P1B-U04-L1',1,'listening.P1B-U04','listening-choice','listen','{"title":"我会做的小动作","gradeMin":1,"id":"P1B-U04-L1.p4.listen","type":"listen","category":"vocabulary","context":"主动播放一句英文，听清后确认；听不到时可用文字辅助。","prompt":"Yaya会敲什么？","audioText":"Yaya can tap the drum.","choices":["鼓","门","桌子"]}','{"answers":["鼓"],"family":"fact-05b65bd830ae10fe","hint":"先听人物、动作、物品或位置。需要时使用文字辅助，辅助会单独记录。","explanation":"Yaya can tap the drum. 对应答案：鼓。","solutionSentences":["Yaya can tap the drum."]}','published');
