INSERT INTO items VALUES('P1B-U04-L1.p5.evidence',1,'P1B-U04-L1',1,'reading.P1B-U04','reading-evidence','evidence','{"title":"我会做的小动作","gradeMin":1,"id":"P1B-U04-L1.p5.evidence","type":"evidence","category":"reading","context":"读小故事，先选支持答案的原句，再回答问题。","prompt":"Didi会画什么？","passage":[{"id":"s1","text":"Bobo can catch a soft ball."},{"id":"s2","text":"Didi can draw a smiling sun."},{"id":"s3","text":"They practise different actions."}],"choices":["a smiling sun","a blue boat","a tall tree"]}','{"answers":["[\"s2\",\"a smiling sun\"]"],"evidenceSolutions":[{"sentenceId":"s2","answer":"a smiling sun"}],"family":"fact-bcb05190c0b49178","hint":"回到原文找人物、地点、物品或因果；所选句子必须支持答案。","explanation":"依据：Didi can draw a smiling sun. 对应答案：a smiling sun。","solutionSentences":["Didi can draw a smiling sun."]}','published');
