INSERT INTO items VALUES('P3B-U04-L2.p3.choice',1,'P3B-U04-L2',1,'grammar.connectives.reason','recognition','choice','{"title":"天气理由要有依据","gradeMin":3,"id":"P3B-U04-L2.p3.choice","type":"choice","category":"grammar","context":"选择表示原因的连接词。","prompt":"We dry the paint indoors ___ the courtyard is damp.","choices":["because","or","but"]}','{"answers":["because"],"family":"fact-fc9a0dc6dfef980f","hint":"天气因地区而不同，不能说每个地方冬天都下雪。阅读先找人物所在的地方和原文天气，再用because解释选择。原文没说的原因不能当成证据。","explanation":"We dry the paint indoors because the courtyard is damp. 选择表示原因的连接词。 天气因地区而不同，不能说每个地方冬天都下雪。阅读先找人物所在的地方和原文天气，再用because解释选择。原文没说的原因不能当成证据。","solutionSentences":["We dry the paint indoors because the courtyard is damp."]}','published');
