INSERT INTO items VALUES('P3B-U04-L4.p2.evidence',1,'P3B-U04-L4',1,'reading.P3B-U04','reading-evidence','evidence','{"title":"季节喜好各有理由","gradeMin":3,"id":"P3B-U04-L4.p2.evidence","type":"evidence","category":"reading","context":"读小故事，先选支持答案的原句，再回答问题。","prompt":"Nala喜欢冬天的理由是什么？","passage":[{"id":"s1","text":"Nala prefers winter because she likes the quiet garden."},{"id":"s2","text":"Ravi prefers spring because he likes watching seedlings grow."},{"id":"s3","text":"Neither child has to change the other''s favourite."}],"choices":["she likes the quiet garden","she likes snowy mountains","she likes long hot days"]}','{"answers":["[\"s1\",\"she likes the quiet garden\"]"],"evidenceSolutions":[{"sentenceId":"s1","answer":"she likes the quiet garden"}],"family":"fact-f2ad330872627169","hint":"回到原文找人物、地点、物品或因果；所选句子必须支持答案。","explanation":"依据：Nala prefers winter because she likes the quiet garden. 对应答案：she likes the quiet garden。","solutionSentences":["Nala prefers winter because she likes the quiet garden."]}','published');
