INSERT INTO items VALUES('P3B-U04-L4.p3.choice',1,'P3B-U04-L4',1,'grammar.connectives.contrast','recognition','choice','{"title":"季节喜好各有理由","gradeMin":3,"id":"P3B-U04-L4.p3.choice","type":"choice","category":"grammar","context":"把两个不同喜好连接起来，用but。","prompt":"Zeno likes warm days, ___ Esme likes cool days.","choices":["but","because","so"]}','{"answers":["but"],"family":"fact-3be66d05dbff5533","hint":"别人喜欢的季节可以和自己不同。读Why…?先找对应人物的because原因。but连接不同看法，because说明自己的理由；有证据的喜好没有统一正确季节。","explanation":"Zeno likes warm days, but Esme likes cool days. 把两个不同喜好连接起来，用but。 别人喜欢的季节可以和自己不同。读Why…?先找对应人物的because原因。but连接不同看法，because说明自己的理由；有证据的喜好没有统一正确季节。","solutionSentences":["Zeno likes warm days, but Esme likes cool days."]}','published');
