INSERT INTO items VALUES('P3B-U04-L4.p6.repair',1,'P3B-U04-L4',1,'grammar.connectives.reason','sentence-editing','repair','{"title":"季节喜好各有理由","gradeMin":3,"id":"P3B-U04-L4.p6.repair","type":"repair","category":"grammar","context":"后半句说明理由，用because。","prompt":"点选一处需要修改的词块，填写改后的词；只改这一处。","editing":{"parts":[{"id":"p0","text":"Hana"},{"id":"p1","text":"likes"},{"id":"p2","text":"spring"},{"id":"p3","text":"but"},{"id":"p4","text":"she"},{"id":"p5","text":"enjoys"},{"id":"p6","text":"the"},{"id":"p7","text":"fresh"},{"id":"p8","text":"leaves"},{"id":"p9","text":"."}]}}','{"answers":["[\"p3\",\"because\"]"],"repairs":[{"partId":"p3","replacements":["because"]}],"family":"fact-950a7efa74e4210a","hint":"别人喜欢的季节可以和自己不同。读Why…?先找对应人物的because原因。but连接不同看法，because说明自己的理由；有证据的喜好没有统一正确季节。","explanation":"Hana likes spring because she enjoys the fresh leaves. 后半句说明理由，用because。 别人喜欢的季节可以和自己不同。读Why…?先找对应人物的because原因。but连接不同看法，because说明自己的理由；有证据的喜好没有统一正确季节。","solutionSentences":["Hana likes spring because she enjoys the fresh leaves."],"evidenceTargets":[]}','published');
