INSERT INTO items VALUES('P3B-U04-L4.p7.sort',1,'P3B-U04-L4',1,'grammar.connectives.reason','rule-classification','sort','{"title":"季节喜好各有理由","gradeMin":3,"id":"P3B-U04-L4.p7.sort","type":"sort","category":"grammar","context":"看清两个篮子的意思，把四张卡片分好；可以改放，不计速度。","prompt":"先点卡片，再点篮子，全部放好后一起检查。","sorting":{"cards":[{"id":"cc358b2e207b9","text":"I like misty days because they feel calm."},{"id":"cc4579a839cb3","text":"I like autumn because I enjoy leaf colours."},{"id":"c2bc5821a991f","text":"I like winter, but my cousin likes summer."},{"id":"cbcdca2fe5137","text":"I enjoy rain, but my friend enjoys sunshine."}],"groups":[{"id":"g0","label":"在解释理由"},{"id":"g1","label":"在对比喜好"}]}}','{"answers":["[[\"c2bc5821a991f\",\"g1\"],[\"cbcdca2fe5137\",\"g1\"],[\"cc358b2e207b9\",\"g0\"],[\"cc4579a839cb3\",\"g0\"]]"],"placements":{"cc358b2e207b9":"g0","cc4579a839cb3":"g0","c2bc5821a991f":"g1","cbcdca2fe5137":"g1"},"family":"workshop-set-94a16b25122844d6","hint":"别人喜欢的季节可以和自己不同。读Why…?先找对应人物的because原因。but连接不同看法，because说明自己的理由；有证据的喜好没有统一正确季节。","explanation":"I like misty days because they feel calm. → 在解释理由；I like autumn because I enjoy leaf colours. → 在解释理由；I like winter, but my cousin likes summer. → 在对比喜好；I enjoy rain, but my friend enjoys sunshine. → 在对比喜好","solutionSentences":["I like misty days because they feel calm. → 在解释理由","I like autumn because I enjoy leaf colours. → 在解释理由","I like winter, but my cousin likes summer. → 在对比喜好","I enjoy rain, but my friend enjoys sunshine. → 在对比喜好"],"evidenceTargets":["workshop-target:grammar.connectives.reason:cc358b2e207b9","workshop-target:grammar.connectives.reason:cc4579a839cb3","workshop-target:grammar.connectives.reason:c2bc5821a991f","workshop-target:grammar.connectives.reason:cbcdca2fe5137"]}','published');
