INSERT INTO items VALUES('P6B-U04-L4.p2.evidence',1,'P6B-U04-L4',1,'reading.P6B-U04','reading-evidence','evidence','{"title":"轮流倾听再作决定","gradeMin":6,"id":"P6B-U04-L4.p2.evidence","type":"evidence","category":"reading","context":"读小故事，先选支持答案的原句，再回答问题。","prompt":"记录能确定什么？","passage":[{"id":"s1","text":"Meeting note: Isha suggests a puppet show, and Theo suggests a comic. No vote has taken place."},{"id":"s2","text":"Rin has not replied yet, so the group asks for Rin''s view before deciding."},{"id":"s3","text":"Silence is not recorded as agreement."}],"choices":["two ideas have been suggested","the group has chosen the puppet show","the group has rejected the comic"]}','{"answers":["[\"s1\",\"two ideas have been suggested\"]"],"evidenceSolutions":[{"sentenceId":"s1","answer":"two ideas have been suggested"}],"family":"fact-4a3c5905add82bb2","hint":"回到原文找人物、地点、物品或因果；所选句子必须支持答案。","explanation":"依据：Meeting note: Isha suggests a puppet show, and Theo suggests a comic. No vote has taken place. 对应答案：two ideas have been suggested。","solutionSentences":["Meeting note: Isha suggests a puppet show, and Theo suggests a comic. No vote has taken place."]}','published');
