INSERT INTO items VALUES('P6B-U04-L4.p3.choice',1,'P6B-U04-L4',1,'grammar.suggestions.lets','recognition','choice','{"title":"轮流倾听再作决定","gradeMin":6,"id":"P6B-U04-L4.p3.choice","type":"choice","category":"grammar","context":"Let''s后用listen原形。","prompt":"Let''s ___ to the last speaker before choosing.","choices":["listen","listening","to listen"]}','{"answers":["listen"],"family":"fact-7bb0bdcd7b43c14a","hint":"讨论记录要分清谁建议、谁同意、哪些仍未决定。Let''s加原形邀请一起做；Shall we加原形询问一起做某事。听见一个人说could不能写成全组will；也不能把未回复当成同意。","explanation":"Let''s listen to the last speaker before choosing. Let''s后用listen原形。 讨论记录要分清谁建议、谁同意、哪些仍未决定。Let''s加原形邀请一起做；Shall we加原形询问一起做某事。听见一个人说could不能写成全组will；也不能把未回复当成同意。","solutionSentences":["Let''s listen to the last speaker before choosing."]}','published');
